#!/usr/bin/env node
'use strict';

/**
 * agent-files-state.cjs - Shared detection for missing root agent-instruction files.
 *
 * Two root files bootstrap a portable .claude install:
 *   - CLAUDE.md  — Claude Code root instructions. Generated by /claude-md-init
 *                  (reads docs/project-config.json + template). AI-runnable.
 *   - AGENTS.md  — Codex/cross-tool root instructions. Generated mirror of CLAUDE.md
 *                  produced by /sync-codex or its standalone node runner.
 *
 * This lib is the single source of truth for "is a root agent file missing and what
 * fixes it" — consumed by the UserPromptSubmit router (init-prompt-gate.cjs), now the sole
 * agent-files bootstrap router (the PreToolUse agent-files-skill-gate.cjs Skill router was
 * removed in the de-hooking refactor). Pure detection: no process.exit.
 *
 * Path resolution uses CLAUDE_PROJECT_DIR so a copied .claude bootstraps in any folder.
 *
 * @module agent-files-state
 */

const fs = require('fs');
const path = require('path');
const { AGENT_FILES_DISMISSED_PATH, ensureProjectTmpDir } = require('./ck-paths.cjs');
const { getConfiguredProjectConfigPath } = require('./project-config-loader.cjs');
const { resolveProjectRoot } = require('./project-root.cjs');

const rootResolution = resolveProjectRoot({ cwd: process.cwd(), scriptPath: __filename, env: process.env });
const PROJECT_DIR = rootResolution.rootDir;
const DISMISS_TTL_MS = 24 * 60 * 60 * 1000; // 1 day — matches the other init gates

// ── Universal-guides content contract ──────────────────────────────────────
// An existing CLAUDE.md/AGENTS.md is "complete" only if it carries the portable
// framework guides (workflow ask-confirm gate, workflow step-advancement + parallel-
// phase barrier, task-planning, code hierarchy, evidence rules).
// CANONICAL contract: the generator (claude-md-init/scripts/generate-claude-md.cjs)
// stamps the sentinel below; bumping UNIVERSAL_GUIDES_VERSION re-offers an update on
// every previously-stamped file. The agent-files-gate.test.cjs sync test asserts the
// generator emits a marker matching this version — keep them in lockstep.
const UNIVERSAL_GUIDES_VERSION = 6;
const SENTINEL_RE = /<!--\s*CK:UNIVERSAL-GUIDES\s+v(\d+)\s*-->/i;
// Fallback for legacy/hand-written files with no sentinel: the static portable
// section headings the template always ships (see claude-md-template.md).
const REQUIRED_ANCHORS = [
    /first action decision/i, // the workflow ask-confirm gate
    /workflow step advancement/i, // model-driven advancement + parallel-phase barrier (hook-free, portable)
    /task planning rules/i,
    /code responsibility hierarchy/i,
    /evidence-based reasoning/i,
    /lesson extraction/i, // self-improvement /learn gate (hook-free, portable) — v5
    /version-control discipline/i // git-commit safety guardrail (hook-free, portable) — v6
];

// ── Shared-protocol content contract ───────────────────────────────────────
// Beyond the prose guides, a complete root context file MUST carry the always-on
// shared hookless protocol (critical-thinking + ai-mistake-prevention) baked from the
// canonical `:full` blocks. A file may carry the sentinel/anchors yet have lost the
// protocol bake (e.g. an old generator stamped before protocol baking existed) — that
// file must still route to `update` so it self-heals. Detection covers BOTH surface
// representations because the two generators emit different markup for the same body:
//   - CLAUDE.md (generate-claude-md.cjs): wraps each block in CK: HTML markers.
//   - AGENTS.md (sync-context-workflows.mjs): bakes the canonical `:full` body into
//     `.codex/CODEX_CONTEXT.md` and leaves AGENTS.md a bounded pointer to it — so probe
//     the pointer and follow it, never the body inline (see the contract note below).
// The probes are file-specific so a CLAUDE.md never passes on AGENTS.md-only markup
// and vice-versa; getAgentFileIssues() selects the probe via the AGENT_FILES entry.
const CK_PROTOCOL_MARKERS = [/<!--\s*CK:CRITICAL-THINKING\s*-->/i, /<!--\s*CK:AI-MISTAKE-PREVENTION\s*-->/i];
// Canonical phrases the `:full` bodies always emit (verbatim heading/lead line from
// sync-inline-versions.md `critical-thinking-mindset:full` + `ai-mistake-prevention:full`).
// Stable across the Codex tool-term rewrite (neither phrase contains a rewritten token).
const CANONICAL_PROTOCOL_PHRASES = [/\[CRITICAL-THINKING-MINDSET\]/, /Common AI Mistake Prevention \(System Lessons\)/i];
// This gate does NOT require those phrases inline in AGENTS.md, and must not — but the reason
// is reachability, not prohibition. Two facts govern:
//
//   1. Whether AGENTS.md carries the body at all is PROJECT-DEPENDENT. Its copy is CLAUDE.md-
//      derived through the projection whitelist, so a root whose CLAUDE.md carries the CK fences
//      gets exactly one deduped copy, and a fence-less root legitimately gets zero. Requiring the
//      body here would fire forever on every fence-less project while its own remedy (re-run the
//      sync) regenerated the same, correct, body-less file — the "incomplete forever" dead end.
//   2. Enforcing the exact count is a DIFFERENT gate's job. `verify-skill-protocol-compliance.mjs`
//      (checkProtocolBodySignatureCounts) owns it and applies the same conditional rule: exactly 1
//      when CLAUDE.md carries that block's CK fence, exactly 0 when it does not, >=2 never.
//
// What this gate owns is REACHABILITY: the protocol body must be reachable from AGENTS.md whether
// or not the root inlines it. The always-present carrier is `.codex/CODEX_CONTEXT.md`, whose copy
// is baked from the canonical shared source and is therefore project-independent. So probe the
// context POINTER, then follow it to the body — a check that holds for fenced and fence-less roots
// alike.
//
// (Historical note: this comment once asserted the body was unsatisfiable inline against a
// 32 768-byte bound. That budget was raised to 49 152 — `AGENTS_ROOT_LIMIT_BYTES`, pinned equal in
// verify-skill-protocol-compliance.mjs and sync-context-workflows.mjs — so the arithmetic no longer
// holds and the root does now carry the blocks in this repo. Do not restore the old rationale.)
const CODEX_CONTEXT_RELATIVE = path.join('.codex', 'CODEX_CONTEXT.md');
const AGENTS_CONTEXT_POINTER = [
    /<!--\s*CODEX-CONTEXT-MIRROR:START\s*-->/i,
    /<!--\s*CODEX-CONTEXT-MIRROR:END\s*-->/i,
    /Context fingerprint \(SHA-256\):\s*[0-9a-f]{64}/i
];

/**
 * Does this CLAUDE.md content carry the marker-wrapped shared protocol blocks?
 * @param {string} content
 * @returns {boolean}
 */
function hasClaudeProtocol(content) {
    const text = content || '';
    return CK_PROTOCOL_MARKERS.every(re => re.test(text));
}

/**
 * Does this AGENTS.md content reach the canonical shared-protocol body?
 * AGENTS.md is a bounded projection, so completeness = it carries the context pointer AND
 * the pointed-to `.codex/CODEX_CONTEXT.md` actually carries the protocol body. A pointer to
 * a missing or protocol-less context file is genuinely incomplete and correctly routes to the
 * sync, which regenerates that context file. Enforcing that AGENTS.md does not ALSO duplicate
 * the body is verify-skill-protocol-compliance.mjs's job, not this gate's.
 * @param {string} content
 * @returns {boolean}
 */
function hasAgentsProtocol(content) {
    const text = content || '';
    if (!AGENTS_CONTEXT_POINTER.every(re => re.test(text))) return false;
    const contextPath = path.join(PROJECT_DIR, CODEX_CONTEXT_RELATIVE);
    let context;
    try {
        if (!fs.existsSync(contextPath)) return false; // pointer to nothing → sync must regenerate
        context = fs.readFileSync(contextPath, 'utf-8');
    } catch {
        return true; // fail-open: an unreadable context file must not nag on every prompt
    }
    return CANONICAL_PROTOCOL_PHRASES.every(re => re.test(context));
}

/**
 * Canonical root agent files and the skill that (re)generates each.
 * `aiRunnable` distinguishes routes Claude can invoke itself (/claude-md-init) from
 * routes that may need a standalone script fallback.
 * `updateArgs` is the smart-merge argument for THAT file's runner, and must stay per-file:
 * `--mode update` is a flag of generate-claude-md.cjs only. run-codex-sync.mjs does not
 * parse it — an unrecognized flag there is silently ignored and the full 18-stage mutating
 * pipeline runs instead, so advertising it on the AGENTS.md route told the reader to run
 * something other than what they would get.
 */
const AGENT_FILES = [
    {
        file: 'CLAUDE.md',
        route: '/claude-md-init',
        aiRunnable: true,
        updateArgs: '--mode update',
        why: 'Claude Code root instructions — generated from docs/project-config.json + template.',
        // Per-file shared-protocol probe (CK: HTML markers — the CLAUDE.md surface form).
        hasProtocol: hasClaudeProtocol
    },
    {
        file: 'AGENTS.md',
        route: '/sync-codex',
        aiRunnable: false,
        fallbackCommand: 'node .claude/skills/sync-codex/scripts/run-codex-sync.mjs',
        // No flag: the sync regenerates AGENTS.md from canonical CLAUDE.md on a plain run.
        updateArgs: '',
        why: 'Codex/cross-tool root instructions — generated mirror of CLAUDE.md.',
        // Per-file shared-protocol probe (canonical `:full` body — AGENTS.md emits no CK: markers).
        hasProtocol: hasAgentsProtocol
    }
];

/**
 * Does this content already carry the universal portable guides?
 * Hybrid: current-or-newer sentinel wins; otherwise fall back to requiring every
 * static anchor (covers legacy/hand-written-complete files with no sentinel).
 * @param {string} content
 * @returns {boolean}
 */
function hasUniversalGuides(content) {
    const text = content || '';
    const m = text.match(SENTINEL_RE);
    if (m) return Number(m[1]) >= UNIVERSAL_GUIDES_VERSION;
    return REQUIRED_ANCHORS.every(re => re.test(text));
}

/**
 * Is the universal-guides content check enabled for this project?
 * Opt-out: portability.requireUniversalGuides === false keeps a project-only file.
 * Defaults to true (and fail-open to true on any config read error).
 * @returns {boolean}
 */
function isUniversalGuidesRequired() {
    try {
        const configPath = getConfiguredProjectConfigPath();
        if (!fs.existsSync(configPath)) return true;
        const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
        return config?.portability?.requireUniversalGuides !== false;
    } catch {
        return true; // fail-safe: default to requiring guides
    }
}

/**
 * Classify each root agent file: missing (route to init), incomplete (exists but
 * lacks the universal guides → route to update/smart-merge, preserving project
 * content), or ok (omitted). The incomplete check is skipped when the project has
 * opted out via portability.requireUniversalGuides.
 * @returns {Array<{file:string, route:string, aiRunnable:boolean, why:string, reason:'missing'|'incomplete', mode:'init'|'update'}>}
 */
function getAgentFileIssues() {
    const requireGuides = isUniversalGuidesRequired();
    const issues = [];
    for (const entry of AGENT_FILES) {
        const full = path.join(PROJECT_DIR, entry.file);
        let exists;
        try {
            exists = fs.existsSync(full);
        } catch {
            continue; // fail-open: unreadable → don't claim an issue
        }
        if (!exists) {
            issues.push({ ...entry, reason: 'missing', mode: 'init' });
            continue;
        }
        if (!requireGuides) continue; // existing file accepted as-is (opted out)
        let content;
        try {
            content = fs.readFileSync(full, 'utf-8');
        } catch {
            continue; // fail-open: unreadable → don't claim incomplete
        }
        // Completeness = prose guides AND the shared hookless protocol. A file with the
        // sentinel/anchors but WITHOUT the protocol bake (the stale-CLAUDE.md defect) is
        // incomplete → routed to `update` so the generator re-bakes the protocol and self-heals.
        const protocolPresent = typeof entry.hasProtocol === 'function' ? entry.hasProtocol(content) : true;
        const guidesPresent = hasUniversalGuides(content);
        if (!guidesPresent || !protocolPresent) {
            // Name WHICH half failed. Reporting every incomplete file as "missing the universal
            // portable guides" misdiagnoses a protocol-only failure and sends the reader looking
            // for absent guides that are in fact present.
            const missing = !guidesPresent && !protocolPresent ? 'both' : (guidesPresent ? 'protocol' : 'guides');
            issues.push({ ...entry, reason: 'incomplete', mode: 'update', missing });
        }
    }
    return issues;
}

/**
 * Which root agent files are missing from the project root (existence only).
 * Retained for back-compat; new callers should prefer getAgentFileIssues().
 * @returns {Array<{file:string, route:string, aiRunnable:boolean, why:string}>}
 */
function getMissingAgentFiles() {
    return AGENT_FILES.filter(entry => {
        try {
            return !fs.existsSync(path.join(PROJECT_DIR, entry.file));
        } catch {
            return false; // fail-open: unreadable → don't claim missing
        }
    });
}

/**
 * True when at least one root agent file is missing or incomplete.
 * @returns {boolean}
 */
function hasMissingAgentFiles() {
    return getAgentFileIssues().length > 0;
}

/**
 * Dismiss flag valid (< TTL old)?
 * @returns {boolean}
 */
function isAgentFilesDismissed() {
    try {
        if (!fs.existsSync(AGENT_FILES_DISMISSED_PATH)) return false;
        const ageMs = Date.now() - fs.statSync(AGENT_FILES_DISMISSED_PATH).mtimeMs;
        return ageMs < DISMISS_TTL_MS;
    } catch {
        return false;
    }
}

/**
 * Write the dismiss flag with current timestamp.
 */
function writeAgentFilesDismissFlag() {
    if (rootResolution.error) return;
    try {
        ensureProjectTmpDir();
        fs.writeFileSync(AGENT_FILES_DISMISSED_PATH, new Date().toISOString() + '\n', 'utf-8');
    } catch {
        /* non-critical */
    }
}

/**
 * Is the prompt a dismiss request? Shares the "skip init" / "skip setup" phrase with
 * the project-config gate so one phrase silences the whole init nag for a day.
 * @param {string} prompt
 * @returns {boolean}
 */
function isAgentFilesDismissRequest(prompt) {
    return /skip\s*(init|setup)/i.test(prompt || '');
}

/**
 * Build the offer message instructing the AI to auto-route setup work.
 * Accepts getAgentFileIssues() output (entries carry reason/mode); also tolerates
 * legacy getMissingAgentFiles() output (no reason → treated as missing).
 * @param {Array} issues - output of getAgentFileIssues() (or getMissingAgentFiles())
 * @returns {string}
 */
function buildOfferMessage(issues) {
    const lines = issues.map(m => {
        const fallback = m.fallbackCommand ? ` or \`${m.fallbackCommand}\`` : '';
        const runner = m.aiRunnable ? `run ${m.route}${fallback}` : `ask the user to run ${m.route}${fallback}`;
        if (m.reason === 'incomplete') {
            const updateArgs = m.updateArgs ? ` ${m.updateArgs}` : '';
            const what = m.missing === 'protocol' ? 'the always-on shared protocol'
                : m.missing === 'both' ? 'the universal portable guides and the shared protocol'
                    : 'the universal portable guides';
            return `  - ${m.file} present but missing ${what} → ${runner}${updateArgs} (smart-merge — preserves your project content)`;
        }
        return `  - ${m.file} missing → ${runner}`;
    });
    return [
        '',
        'Root agent-instruction file(s) need attention:',
        ...lines,
        '',
        'Preferred route:',
        '  /project-init        — initialize/re-evaluate config, docs, CLAUDE.md, AGENTS.md, and mirrors',
        '',
        'Targeted routes:',
        '  /claude-md-init       — generate or smart-merge CLAUDE.md from project-config + template',
        '  /sync-codex           — user-invoked only; generate AGENTS.md (Codex mirror of CLAUDE.md); use the node runner if the skill is unavailable',
        '  opt out permanently   — set portability.requireUniversalGuides=false in docs/project-config.json',
        '                          to keep a project-only file (disables the content check, not existence)',
        ''
    ].join('\n');
}

module.exports = {
    AGENT_FILES,
    DISMISS_TTL_MS,
    UNIVERSAL_GUIDES_VERSION,
    SENTINEL_RE,
    REQUIRED_ANCHORS,
    CK_PROTOCOL_MARKERS,
    CANONICAL_PROTOCOL_PHRASES,
    hasUniversalGuides,
    hasClaudeProtocol,
    hasAgentsProtocol,
    isUniversalGuidesRequired,
    getAgentFileIssues,
    getMissingAgentFiles,
    hasMissingAgentFiles,
    isAgentFilesDismissed,
    writeAgentFilesDismissFlag,
    isAgentFilesDismissRequest,
    buildOfferMessage
};
